from pathlib import Path

MODELS = Path('platform_core/task_runtime/models.py')
REPOSITORY = Path('platform_core/task_runtime/repository.py')
INIT = Path('platform_core/task_runtime/__init__.py')
PUBLIC = Path('platform_core/task_runtime/public.py')
APP = Path('app.py')
UNIT = Path('tests/unit/task_runtime/test_public_projection.py')
API = Path('tests/api/test_unified_task_runtime.py')

models = MODELS.read_text(encoding='utf-8')
old = '''    finished_at: str | None = None\n    resource_wait_reason: str | None = None\n'''
new = '''    finished_at: str | None = None\n    resource_wait_reason: str | None = None\n    queue_rank: int = 0\n    worker_id: str | None = None\n    lease_expires_at: str | None = None\n'''
if models.count(old) != 1:
    raise SystemExit(f'model TaskRecord anchor count={models.count(old)}')
MODELS.write_text(models.replace(old, new, 1), encoding='utf-8')

repo = REPOSITORY.read_text(encoding='utf-8')
old = '''        finished_at=row["finished_at"],\n        resource_wait_reason=row["resource_wait_reason"],\n    )\n'''
new = '''        finished_at=row["finished_at"],\n        resource_wait_reason=row["resource_wait_reason"],\n        queue_rank=int(row["queue_rank"] or 0),\n        worker_id=row["worker_id"],\n        lease_expires_at=row["lease_expires_at"],\n    )\n'''
if repo.count(old) != 1:
    raise SystemExit(f'repository row projection anchor count={repo.count(old)}')
repo = repo.replace(old, new, 1)
anchor = '''    def list(\n        self,\n        project_id: str | None = None,\n'''
method = '''    def resource_queue_position(self, task_id: str) -> int | None:\n        """Return the truthful ordering position among queued peers sharing a resource key.\n\n        This is intentionally resource-scoped rather than a fake global queue position:\n        different worker roles/capabilities may consume independent queues concurrently.\n        """\n        with self._connect() as database:\n            row = database.execute(\n                "SELECT task_id,status,priority,queue_rank,resource_key,created_at FROM tasks WHERE task_id=?",\n                (str(task_id),),\n            ).fetchone()\n            if row is None:\n                raise KeyError(task_id)\n            if str(row["status"]) != TaskStatus.QUEUED.value:\n                return None\n            ahead = database.execute(\n                """\n                SELECT COUNT(*) FROM tasks\n                 WHERE status='QUEUED' AND resource_key=? AND task_id<>?\n                   AND (\n                        priority < ?\n                        OR (priority = ? AND queue_rank > ?)\n                        OR (priority = ? AND queue_rank = ? AND created_at < ?)\n                        OR (priority = ? AND queue_rank = ? AND created_at = ? AND task_id < ?)\n                   )\n                """,\n                (\n                    str(row["resource_key"]), str(row["task_id"]),\n                    int(row["priority"]),\n                    int(row["priority"]), int(row["queue_rank"] or 0),\n                    int(row["priority"]), int(row["queue_rank"] or 0), str(row["created_at"]),\n                    int(row["priority"]), int(row["queue_rank"] or 0), str(row["created_at"]), str(row["task_id"]),\n                ),\n            ).fetchone()[0]\n        return int(ahead) + 1\n\n'''
if repo.count(anchor) != 1:
    raise SystemExit(f'repository list anchor count={repo.count(anchor)}')
repo = repo.replace(anchor, method + anchor, 1)
REPOSITORY.write_text(repo, encoding='utf-8')

PUBLIC.write_text('''from __future__ import annotations\n\nfrom typing import Any\n\nfrom .models import TaskRecord, TaskStatus\nfrom .repository import TaskRepository\n\n\ndef effective_task_status(task: TaskRecord) -> str:\n    if task.status is TaskStatus.QUEUED and task.stage == "resource_waiting":\n        return "WAITING_RESOURCE"\n    return task.status.value\n\n\ndef task_to_public(task: TaskRecord, repository: TaskRepository | None = None) -> dict[str, Any]:\n    queue_position = None\n    if repository is not None and task.status is TaskStatus.QUEUED:\n        queue_position = repository.resource_queue_position(task.task_id)\n    return {\n        "task_id": task.task_id,\n        "project_id": task.project_id,\n        "task_type": task.kind.value,\n        "status": effective_task_status(task),\n        "persisted_status": task.status.value,\n        "phase": task.stage,\n        "progress_percent": max(0.0, min(100.0, float(task.progress))),\n        "current_item": task.current_item,\n        "priority": int(task.priority),\n        "queue_rank": int(task.queue_rank),\n        "resource_queue_position": queue_position,\n        "resource_key": task.resource_key,\n        "resource_wait_reason": task.resource_wait_reason,\n        "required_capabilities": list(task.required_capabilities),\n        "worker_id": task.worker_id,\n        "lease_expires_at": task.lease_expires_at,\n        "attempt": int(task.attempt),\n        "retry_of": task.retry_of,\n        "error": task.error,\n        "accepted": task.accepted,\n        "created_at": task.created_at,\n        "updated_at": task.updated_at,\n        "finished_at": task.finished_at,\n    }\n''', encoding='utf-8')

init = INIT.read_text(encoding='utf-8')
if 'from .public import effective_task_status, task_to_public\n' not in init:
    init = init.replace('from .repository import TaskRepository\n', 'from .repository import TaskRepository\nfrom .public import effective_task_status, task_to_public\n', 1)
    init = init.replace('    "TaskStatus",\n', '    "TaskStatus",\n    "effective_task_status",\n    "task_to_public",\n', 1)
INIT.write_text(init, encoding='utf-8')

app = APP.read_text(encoding='utf-8')
import_old = '''    TaskRepository,\n    TaskStatus,\n)\n'''
import_new = '''    TaskRepository,\n    TaskStatus,\n    task_to_public,\n)\n'''
if app.count(import_old) != 1:
    raise SystemExit(f'app task-runtime import anchor count={app.count(import_old)}')
app = app.replace(import_old, import_new, 1)

endpoint_anchor = '''@app.get("/api/system/version")\ndef system_version():\n    return {\n        "version": APP_VERSION,\n        "name": "畅联云算法训练",\n        "data_dir": str(DATA_DIR),\n        "base_dir": str(BASE_DIR),\n        "persistent": True,\n    }\n\n'''
endpoints = endpoint_anchor + '''def _runtime_task_for_project(project_id: str, task_id: str) -> TaskRecord:\n    get_project(project_id)\n    task = shared_task_repository().get(task_id)\n    if task is None or task.project_id != project_id:\n        raise HTTPException(status_code=404, detail="任务不存在")\n    return task\n\n\n@app.get("/api/v62/projects/{project_id}/tasks")\ndef list_unified_runtime_tasks(\n    project_id: str,\n    kind: Optional[str] = Query(default=None),\n    limit: int = Query(default=50, ge=1, le=100),\n    cursor: Optional[str] = Query(default=None),\n):\n    get_project(project_id)\n    kinds = None\n    if kind:\n        try:\n            kinds = (TaskKind(str(kind).strip().upper()),)\n        except ValueError as error:\n            raise HTTPException(status_code=422, detail=f"未知任务类型：{kind}") from error\n    repository = shared_task_repository()\n    try:\n        page = repository.list(project_id=project_id, kinds=kinds, limit=limit, cursor=cursor)\n    except ValueError as error:\n        raise HTTPException(status_code=422, detail=str(error)) from error\n    return {\n        "items": [task_to_public(task, repository) for task in page.items],\n        "next_cursor": page.next_cursor,\n    }\n\n\n@app.get("/api/v62/projects/{project_id}/tasks/{task_id}")\ndef get_unified_runtime_task(project_id: str, task_id: str):\n    repository = shared_task_repository()\n    return task_to_public(_runtime_task_for_project(project_id, task_id), repository)\n\n\n@app.post("/api/v62/projects/{project_id}/tasks/{task_id}/promote")\ndef promote_unified_runtime_task(project_id: str, task_id: str):\n    _runtime_task_for_project(project_id, task_id)\n    repository = shared_task_repository()\n    try:\n        task = repository.promote(task_id)\n    except ValueError as error:\n        raise HTTPException(status_code=409, detail=str(error)) from error\n    return task_to_public(task, repository)\n\n\n@app.post("/api/v62/projects/{project_id}/tasks/{task_id}/cancel")\ndef cancel_unified_runtime_task(project_id: str, task_id: str):\n    _runtime_task_for_project(project_id, task_id)\n    repository = shared_task_repository()\n    try:\n        task = repository.request_cancel(task_id)\n    except ValueError as error:\n        raise HTTPException(status_code=409, detail=str(error)) from error\n    return task_to_public(task, repository)\n\n\n'''
if app.count(endpoint_anchor) != 1:
    raise SystemExit(f'app system-version anchor count={app.count(endpoint_anchor)}')
app = app.replace(endpoint_anchor, endpoints, 1)
APP.write_text(app, encoding='utf-8')

UNIT.write_text(r'''from platform_core.task_runtime import TaskKind, TaskRecord, TaskRepository, task_to_public\n\n\ndef add(repository, task_id, priority=50, resource='gpu:0'):\n    return repository.create(TaskRecord.new(\n        task_id, 'project-1', TaskKind.TRAINING, 'request.json', resource,\n        priority=priority, required_capabilities=('cuda',),\n    ))\n\n\ndef test_public_projection_exposes_real_waiting_resource_and_resource_queue_position(tmp_path):\n    repository = TaskRepository(tmp_path / 'tasks.sqlite3')\n    first = add(repository, 'first', priority=5)\n    second = add(repository, 'second', priority=50)\n    assert repository.resource_queue_position(first.task_id) == 1\n    assert repository.resource_queue_position(second.task_id) == 2\n\n    promoted = repository.promote('second')\n    assert promoted.priority == 4\n    assert repository.resource_queue_position('second') == 1\n\n    def deny(database, candidate, worker_id, token, expires_at, now):\n        return False, 'GPU_MEMORY_BUSY'\n\n    assert repository.claim_next('worker', [TaskKind.TRAINING], {'cuda'}, admission=deny) is None\n    waiting = repository.get('second')\n    assert waiting is not None\n    public = task_to_public(waiting, repository)\n    assert public['status'] == 'WAITING_RESOURCE'\n    assert public['persisted_status'] == 'QUEUED'\n    assert public['resource_wait_reason'] == 'GPU_MEMORY_BUSY'\n    assert public['resource_queue_position'] == 1\n\n\ndef test_worker_lease_and_progress_survive_repository_reopen(tmp_path):\n    path = tmp_path / 'tasks.sqlite3'\n    repository = TaskRepository(path)\n    add(repository, 'running', priority=1, resource='gpu:9')\n    lease = repository.claim_next('worker-a800-01', [TaskKind.TRAINING], {'cuda'})\n    assert lease is not None\n    repository.heartbeat(lease.task.task_id, lease.lease_token, progress=37.5, stage='training', current_item='epoch 3/10')\n\n    reopened = TaskRepository(path)\n    task = reopened.get('running')\n    assert task is not None\n    assert task.worker_id == 'worker-a800-01'\n    assert task.lease_expires_at\n    public = task_to_public(task, reopened)\n    assert public['status'] == 'RUNNING'\n    assert public['progress_percent'] == 37.5\n    assert public['phase'] == 'training'\n    assert public['current_item'] == 'epoch 3/10'\n    assert public['worker_id'] == 'worker-a800-01'\n    assert public['lease_expires_at']\n    assert public['resource_queue_position'] is None\n'''.replace('\\n','\n'), encoding='utf-8')

API.write_text(r'''import uuid\n\nimport app as platform_app\nfrom platform_core.task_runtime import TaskKind, TaskRecord\n\n\ndef make_task(project_id, *, priority=50, resource='cpu:unified', capability='unified.test'):\n    task_id = f'unified-{uuid.uuid4().hex[:10]}'\n    return platform_app.shared_task_repository().create(TaskRecord.new(\n        task_id, project_id, TaskKind.DEPLOYMENT_TEST, 'request.json', resource,\n        priority=priority, required_capabilities=(capability,),\n    ))\n\n\ndef test_unified_task_api_reports_real_queue_state_and_promote(client, seeded_project):\n    project_id, _image = seeded_project\n    first = make_task(project_id, priority=10)\n    second = make_task(project_id, priority=50)\n\n    listing = client.get(f'/api/v62/projects/{project_id}/tasks?kind=DEPLOYMENT_TEST')\n    listing.raise_for_status()\n    by_id = {item['task_id']: item for item in listing.json()['items']}\n    assert by_id[first.task_id]['status'] == 'QUEUED'\n    assert by_id[first.task_id]['resource_queue_position'] == 1\n    assert by_id[second.task_id]['resource_queue_position'] == 2\n\n    promoted = client.post(f'/api/v62/projects/{project_id}/tasks/{second.task_id}/promote')\n    promoted.raise_for_status()\n    assert promoted.json()['priority'] < first.priority\n    assert promoted.json()['resource_queue_position'] == 1\n\n\ndef test_unified_task_api_survives_repository_reopen_and_exposes_worker_truth(client, seeded_project):\n    project_id, _image = seeded_project\n    task = make_task(project_id, priority=1, resource='cpu:lease', capability='lease.test')\n    repository = platform_app.shared_task_repository()\n    lease = repository.claim_next('worker-real-01', [TaskKind.DEPLOYMENT_TEST], {'lease.test'})\n    assert lease is not None and lease.task.task_id == task.task_id\n    repository.heartbeat(task.task_id, lease.lease_token, progress=61, stage='running_test', current_item='sample-61')\n\n    # Simulate a new API-side repository object reading the persisted truth.\n    platform_app._SHARED_TASK_REPOSITORY = None\n    response = client.get(f'/api/v62/projects/{project_id}/tasks/{task.task_id}')\n    response.raise_for_status()\n    body = response.json()\n    assert body['status'] == 'RUNNING'\n    assert body['progress_percent'] == 61\n    assert body['phase'] == 'running_test'\n    assert body['current_item'] == 'sample-61'\n    assert body['worker_id'] == 'worker-real-01'\n    assert body['lease_expires_at']\n\n\ndef test_unified_task_cancel_is_real_repository_state(client, seeded_project):\n    project_id, _image = seeded_project\n    task = make_task(project_id, resource='cpu:cancel')\n    response = client.post(f'/api/v62/projects/{project_id}/tasks/{task.task_id}/cancel')\n    response.raise_for_status()\n    assert response.json()['status'] == 'CANCELLED'\n    again = client.get(f'/api/v62/projects/{project_id}/tasks/{task.task_id}')\n    again.raise_for_status()\n    assert again.json()['status'] == 'CANCELLED'\n'''.replace('\\n','\n'), encoding='utf-8')

print('unified task public runtime patch prepared')
